class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        from collections import defaultdict
        deg = [0] * (n + 1)
        shared = defaultdict(int)
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1
            if u > v:
                u, v = v, u
            shared[(u, v)] += 1
        ans = []
        for q in queries:
            cnt = 0
            for a in range(1, n + 1):
                for b in range(a + 1, n + 1):
                    if deg[a] + deg[b] - shared[(a, b)] > q:
                        cnt += 1
            ans.append(cnt)
        return ans

