#include <bits/stdc++.h>
class Solution {
public:
    vector<int> countPairs(int n, vector<vector<int>>& edges, vector<int>& queries) {
        vector<int> deg(n + 1);
        map<pair<int,int>, int> shared;
        for (auto& e : edges) {
            int u = e[0], v = e[1];
            deg[u]++; deg[v]++;
            if (u > v) swap(u, v);
            shared[{u, v}]++;
        }
        vector<int> ans;
        for (int q : queries) {
            long long cnt = 0;
            for (int a = 1; a <= n; a++)
                for (int b = a + 1; b <= n; b++) {
                    auto it = shared.find({a, b});
                    int c = (it == shared.end()) ? 0 : it->second;
                    if (deg[a] + deg[b] - c > q) cnt++;
                }
            ans.push_back((int)cnt);
        }
        return ans;
    }
};

