class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        from collections import defaultdict
        deg = [0] * (n + 1)
        shared = defaultdict(int)
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1
            shared[(min(u, v), max(u, v))] += 1

        sd = sorted(deg[1:])

        def pairs_over(t):
            lo, hi, res = 0, n - 1, 0
            while lo < hi:
                if sd[lo] + sd[hi] > t:
                    res += hi - lo
                    hi -= 1
                else:
                    lo += 1
            return res

        ans = []
        for q in queries:
            base = pairs_over(q)
            for (a, b), c in shared.items():
                s = deg[a] + deg[b]
                if s > q and s - c <= q:
                    base -= 1
            ans.append(base)
        return ans

