#include <bits/stdc++.h>
class Solution {
public:
    vector<int> countPairs(int n, vector<vector<int>>& edges, vector<int>& queries) {
        vector<int> deg(n + 1);
        map<pair<int,int>, int> shared;
        for (auto& e : edges) {
            int u = min(e[0], e[1]), v = max(e[0], e[1]);
            deg[e[0]]++; deg[e[1]]++;
            shared[{u, v}]++;
        }
        vector<int> sd(deg.begin() + 1, deg.end());
        sort(sd.begin(), sd.end());
        auto pairsOver = [&](int t) {
            int lo = 0, hi = n - 1;
            long long res = 0;
            while (lo < hi) {
                if (sd[lo] + sd[hi] > t) { res += hi - lo; hi--; }
                else lo++;
            }
            return res;
        };
        vector<int> ans;
        for (int q : queries) {
            long long base = pairsOver(q);
            for (auto& [p, c] : shared) {
                int s = deg[p.first] + deg[p.second];
                if (s > q && s - c <= q) base--;
            }
            ans.push_back((int)base);
        }
        return ans;
    }
};

