class Solution {
    private int[] sd;

    private long pairsOver(int n, int t) {
        int lo = 0, hi = n - 1;
        long res = 0;
        while (lo < hi) {
            if (sd[lo] + sd[hi] > t) { res += hi - lo; hi--; }
            else lo++;
        }
        return res;
    }

    public int[] countPairs(int n, int[][] edges, int[] queries) {
        int[] deg = new int[n + 1];
        Map<Long, Integer> shared = new HashMap<>();
        for (int[] e : edges) {
            int u = Math.min(e[0], e[1]), v = Math.max(e[0], e[1]);
            deg[e[0]]++;
            deg[e[1]]++;
            shared.merge((long) u * (n + 1) + v, 1, Integer::sum);
        }
        sd = Arrays.copyOfRange(deg, 1, n + 1);
        Arrays.sort(sd);
        int[] ans = new int[queries.length];
        for (int j = 0; j < queries.length; j++) {
            int q = queries[j];
            long base = pairsOver(n, q);
            for (Map.Entry<Long, Integer> en : shared.entrySet()) {
                long key = en.getKey();
                int a = (int) (key / (n + 1)), b = (int) (key % (n + 1));
                int s = deg[a] + deg[b], c = en.getValue();
                if (s > q && s - c <= q) base--;
            }
            ans[j] = (int) base;
        }
        return ans;
    }
}

